create schema if not exists ecos_meta;
revoke all on schema ecos_meta from public;
create table ecos_meta.database_identity (
 singleton boolean primary key default true check(singleton),
 architecture_version text not null check(architecture_version='2.x'),
 schema_version text not null check(schema_version='1.0.0'),
 environment text not null check(environment='development'),
 authority text not null check(authority='non_production'),
 provider_effects_enabled boolean not null check(not provider_effects_enabled));
insert into ecos_meta.database_identity values(true,'2.x','1.0.0','development','non_production',false);
create table ecos_meta.contract_schema (schema_id text primary key, document jsonb not null);
create table ecos_meta.operation_contract (name text primary key, document jsonb not null);
create table ecos_meta.transition_policy (name text primary key, edges jsonb not null);
create table ecos_meta.entity_contract (name text primary key, schema_id text not null references ecos_meta.contract_schema, immutable boolean not null);

