create table ecos.party(id uuid primary key default gen_random_uuid(), business_id text not null unique, name text not null, record_version bigint not null default 1 check(record_version>0));
create table ecos.project(id uuid primary key default gen_random_uuid(), business_id text not null unique, title text not null, record_version bigint not null default 1 check(record_version>0));
create table ecos.artifact(id uuid primary key default gen_random_uuid(), business_id text not null unique, provider text not null, provider_object_id text not null, uri text not null, content_hash text not null check(content_hash ~ '^[a-f0-9]{64}$'), record_version bigint not null default 1 check(record_version>0), unique(provider,provider_object_id));
create table ecos.fact(id uuid primary key default gen_random_uuid(), subject_id uuid not null, statement text not null, source_references jsonb not null, sensitivity text not null check(sensitivity in ('public','internal','confidential','restricted')), record_version bigint not null default 1 check(record_version>0), created_at timestamptz not null default clock_timestamp());

create table ecos.task(
 "id" uuid not null default gen_random_uuid() primary key,
 "schema_version" text not null default '1.0.0' check("schema_version" = '1.0.0'),
 "created_at" timestamptz not null default clock_timestamp(),
 "record_version" bigint not null default 1 check("record_version" >= 1),
 "business_id" text not null,
 "title" text not null,
 "project_id" uuid,
 "lifecycle_state" text not null check("lifecycle_state" in ('draft','open','waiting','completed','cancelled')),
 "wait_reason" text not null check("wait_reason" in ('none','dependency','owner','external','approval','scheduled')),
 "description" text not null
);
insert into ecos_meta.entity_contract values('task','https://contracts.ecos.invalid/v1/task.schema.json',false);
create table ecos.task_assignment(
 "id" uuid not null default gen_random_uuid() primary key,
 "schema_version" text not null default '1.0.0' check("schema_version" = '1.0.0'),
 "created_at" timestamptz not null default clock_timestamp(),
 "record_version" bigint not null default 1 check("record_version" >= 1),
 "task_id" uuid not null,
 "party_id" uuid not null,
 "role" text not null check("role" in ('owner','delegate','reviewer')),
 "effective_from" timestamptz not null,
 "effective_to" timestamptz
);
insert into ecos_meta.entity_contract values('task_assignment','https://contracts.ecos.invalid/v1/task_assignment.schema.json',false);
create table ecos.task_schedule(
 "id" uuid not null default gen_random_uuid() primary key,
 "schema_version" text not null default '1.0.0' check("schema_version" = '1.0.0'),
 "created_at" timestamptz not null default clock_timestamp(),
 "record_version" bigint not null default 1 check("record_version" >= 1),
 "task_id" uuid not null,
 "due_at" timestamptz,
 "follow_up_at" timestamptz,
 "planned_start_at" timestamptz,
 "timezone" text not null,
 "rrule" text,
 "dst_gap_policy" text not null check("dst_gap_policy" in ('skip','next_valid')),
 "dst_fold_policy" text not null check("dst_fold_policy" in ('earlier','later')),
 "recurrence_anchor" text not null check("recurrence_anchor" in ('fixed_calendar','completion_relative','none'))
);
insert into ecos_meta.entity_contract values('task_schedule','https://contracts.ecos.invalid/v1/task_schedule.schema.json',false);
create table ecos.task_dependency(
 "id" uuid not null default gen_random_uuid() primary key,
 "schema_version" text not null default '1.0.0' check("schema_version" = '1.0.0'),
 "created_at" timestamptz not null default clock_timestamp(),
 "record_version" bigint not null default 1 check("record_version" >= 1),
