create table ecos.export_package(id uuid primary key,manifest jsonb not null,content_hash text not null,created_at timestamptz not null default clock_timestamp());
create table ecos_migration.raw_source_row(batch_id uuid not null references ecos_migration.raw_migration_batch,source_locator text not null,raw_value jsonb not null,raw_hash text not null,primary key(batch_id,source_locator));
create table ecos_meta.notification_policy(task_id uuid primary key references ecos.task,recipient_party_id uuid not null references ecos.party,channel text not null check(channel in ('sms','email')),destination_reference text not null,content_artifact_uri text not null,content_hash text not null,policy_key text not null);

